-- Supabase Postgres is the normalized SQL operational database used for deployment.
BEGIN;
CREATE SCHEMA IF NOT EXISTS dbo;
CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS dbo.roles(roleid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,rolename varchar(50) NOT NULL UNIQUE CHECK(rolename IN ('Customer','Staff','Admin')));
CREATE TABLE IF NOT EXISTS dbo.departments(departmentid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,departmentname varchar(150) NOT NULL UNIQUE,isactive boolean NOT NULL DEFAULT true,createdat timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dbo.users(userid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,schoolid varchar(50) NOT NULL UNIQUE,fullname varchar(200) NOT NULL,email varchar(320) NOT NULL UNIQUE,departmentid integer REFERENCES dbo.departments,roleid integer NOT NULL REFERENCES dbo.roles,customertype varchar(100),isactive boolean NOT NULL DEFAULT true,createdat timestamptz NOT NULL DEFAULT now(),updatedat timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dbo.categories(categoryid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,categoryname varchar(150) NOT NULL UNIQUE,isactive boolean NOT NULL DEFAULT true,createdat timestamptz NOT NULL DEFAULT now(),updatedat timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dbo.products(productid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,categoryid integer NOT NULL REFERENCES dbo.categories,sku varchar(100) NOT NULL UNIQUE,productname varchar(200) NOT NULL,description text,price numeric(12,2) NOT NULL CHECK(price>=0),imageurl varchar(1000),isfeatured boolean NOT NULL DEFAULT false,isactive boolean NOT NULL DEFAULT true,createdat timestamptz NOT NULL DEFAULT now(),updatedat timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dbo.productvariants(productvariantid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,productid integer NOT NULL REFERENCES dbo.products,variantname varchar(100) NOT NULL,variantsku varchar(100) NOT NULL UNIQUE,isactive boolean NOT NULL DEFAULT true,createdat timestamptz NOT NULL DEFAULT now(),updatedat timestamptz NOT NULL DEFAULT now(),UNIQUE(productid,variantname));
CREATE TABLE IF NOT EXISTS dbo.inventory(productvariantid integer PRIMARY KEY REFERENCES dbo.productvariants,physicalquantity integer NOT NULL DEFAULT 0 CHECK(physicalquantity>=0),reservedquantity integer NOT NULL DEFAULT 0 CHECK(reservedquantity>=0),reorderlevel integer NOT NULL DEFAULT 0 CHECK(reorderlevel>=0),updatedat timestamptz NOT NULL DEFAULT now(),CHECK(reservedquantity<=physicalquantity));
CREATE TABLE IF NOT EXISTS dbo.reservationstatuses(reservationstatusid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,statusname varchar(50) NOT NULL UNIQUE CHECK(statusname IN ('Pending','Confirmed','Preparing','Ready for Pickup','Completed','Cancelled','Expired')));
CREATE TABLE IF NOT EXISTS dbo.reservations(reservationid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,reference varchar(100) NOT NULL UNIQUE,customerid integer NOT NULL REFERENCES dbo.users,reservationstatusid integer NOT NULL REFERENCES dbo.reservationstatuses,expiresat timestamptz NOT NULL,createdat timestamptz NOT NULL DEFAULT now(),updatedat timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dbo.reservationitems(reservationitemid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,reservationid integer NOT NULL REFERENCES dbo.reservations,productvariantid integer NOT NULL REFERENCES dbo.productvariants,quantity integer NOT NULL CHECK(quantity>0),unitprice numeric(12,2) NOT NULL CHECK(unitprice>=0),UNIQUE(reservationid,productvariantid));
CREATE TABLE IF NOT EXISTS dbo.queuetypes(queuetypeid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,queuetypename varchar(50) NOT NULL UNIQUE CHECK(queuetypename IN ('Express','Regular')));
CREATE TABLE IF NOT EXISTS dbo.queuestatuses(queuestatusid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,statusname varchar(50) NOT NULL UNIQUE CHECK(statusname IN ('Waiting','Serving','Skipped','Completed','Left')));
CREATE TABLE IF NOT EXISTS dbo.queueentries(queueentryid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,queuenumber varchar(100) NOT NULL,customerid integer NOT NULL REFERENCES dbo.users,reservationid integer NOT NULL REFERENCES dbo.reservations,queuetypeid integer NOT NULL REFERENCES dbo.queuetypes,queuestatusid integer NOT NULL REFERENCES dbo.queuestatuses,joinedat timestamptz NOT NULL DEFAULT now(),calledat timestamptz,completedat timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS ux_queue_active_reservation ON dbo.queueentries(reservationid) WHERE completedat IS NULL;
CREATE TABLE IF NOT EXISTS dbo.paymentmethods(paymentmethodid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,paymentmethodname varchar(100) NOT NULL UNIQUE,isactive boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS dbo.transactionstatuses(transactionstatusid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,statusname varchar(50) NOT NULL UNIQUE CHECK(statusname IN ('Completed','Cancelled')));
CREATE TABLE IF NOT EXISTS dbo.transactions(transactionid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,reference varchar(100) NOT NULL UNIQUE,reservationid integer NOT NULL UNIQUE REFERENCES dbo.reservations,customerid integer NOT NULL REFERENCES dbo.users,staffid integer NOT NULL REFERENCES dbo.users,paymentmethodid integer REFERENCES dbo.paymentmethods,transactionstatusid integer NOT NULL REFERENCES dbo.transactionstatuses,totalamount numeric(12,2) NOT NULL CHECK(totalamount>=0),createdat timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dbo.transactionitems(transactionitemid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,transactionid integer NOT NULL REFERENCES dbo.transactions,productvariantid integer NOT NULL REFERENCES dbo.productvariants,quantity integer NOT NULL CHECK(quantity>0),unitprice numeric(12,2) NOT NULL CHECK(unitprice>=0));
CREATE TABLE IF NOT EXISTS dbo.inventorymovementtypes(inventorymovementtypeid integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,movementtypename varchar(50) NOT NULL UNIQUE CHECK(movementtypename IN ('Reserve','Release','Sale','Adjust','Restock')));
CREATE TABLE IF NOT EXISTS dbo.inventorymovements(inventorymovementid bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,productvariantid integer NOT NULL REFERENCES dbo.productvariants,inventorymovementtypeid integer NOT NULL REFERENCES dbo.inventorymovementtypes,previousqty integer NOT NULL,changeqty integer NOT NULL,resultingqty integer NOT NULL CHECK(resultingqty>=0),previousreservedquantity integer NOT NULL DEFAULT 0,resultingreservedquantity integer NOT NULL DEFAULT 0 CHECK(resultingreservedquantity>=0 AND resultingreservedquantity<=resultingqty),relatedreference varchar(100),performedbyuserid integer REFERENCES dbo.users,notes varchar(1000),createdat timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dbo.notifications(notificationid bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,recipientuserid integer NOT NULL REFERENCES dbo.users,notificationtype varchar(100) NOT NULL,title varchar(250) NOT NULL,message text NOT NULL,relatedentity varchar(100),relatedentityid integer,deliverystatus varchar(50),isread boolean NOT NULL DEFAULT false,createdat timestamptz NOT NULL DEFAULT now(),readat timestamptz);
CREATE TABLE IF NOT EXISTS dbo.auditlogs(auditlogid bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,userid integer REFERENCES dbo.users,action varchar(100) NOT NULL,entity varchar(100) NOT NULL,entityid varchar(100),previousvalue jsonb,newvalue jsonb,details jsonb,createdat timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dbo.systemsettings(settingkey varchar(100) PRIMARY KEY,settingvalue varchar(500) NOT NULL,datatype varchar(50) NOT NULL,description varchar(500),updatedat timestamptz NOT NULL DEFAULT now(),updatedbyuserid integer REFERENCES dbo.users);
CREATE TABLE IF NOT EXISTS dbo.idempotencykeys(scope varchar(100) NOT NULL,idempotencykey varchar(200) NOT NULL,entityid varchar(100) NOT NULL,resultreference varchar(100),createdat timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(scope,idempotencykey));
CREATE TABLE IF NOT EXISTS dbo.automationoutbox(automationeventid bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,eventid uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,eventtype varchar(100) NOT NULL,aggregatetype varchar(100) NOT NULL,aggregateid varchar(100) NOT NULL,payload jsonb NOT NULL,status varchar(20) NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Processing','Delivered','Failed','DeadLetter','Superseded')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),nextattemptat timestamptz DEFAULT now(),lockedat timestamptz,processedat timestamptz,deliveredat timestamptz,lasterror varchar(500),supersededat timestamptz,supersededreason varchar(500),createdat timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS ux_outbox_terminal_event ON dbo.automationoutbox(eventtype,aggregatetype,aggregateid) WHERE eventtype IN ('ReservationCancelled','TransactionCompleted');
COMMENT ON TABLE dbo.roles IS 'Application authorization roles'; COMMENT ON TABLE dbo.departments IS 'School departments'; COMMENT ON TABLE dbo.users IS 'Auth0-mapped application users'; COMMENT ON TABLE dbo.categories IS 'Catalog categories'; COMMENT ON TABLE dbo.products IS 'Catalog products'; COMMENT ON TABLE dbo.productvariants IS 'Sellable product variants'; COMMENT ON TABLE dbo.inventory IS 'Current physical and reserved stock'; COMMENT ON TABLE dbo.reservationstatuses IS 'Reservation status reference data'; COMMENT ON TABLE dbo.reservations IS 'Customer reservation headers'; COMMENT ON TABLE dbo.reservationitems IS 'Reserved variant line items'; COMMENT ON TABLE dbo.queuetypes IS 'Pickup queue type reference data'; COMMENT ON TABLE dbo.queuestatuses IS 'Pickup queue status reference data'; COMMENT ON TABLE dbo.queueentries IS 'Customer pickup queue entries'; COMMENT ON TABLE dbo.paymentmethods IS 'Accepted payment methods'; COMMENT ON TABLE dbo.transactionstatuses IS 'Sale status reference data'; COMMENT ON TABLE dbo.transactions IS 'Completed sale headers'; COMMENT ON TABLE dbo.transactionitems IS 'Sale line items'; COMMENT ON TABLE dbo.inventorymovementtypes IS 'Stock movement type reference data'; COMMENT ON TABLE dbo.inventorymovements IS 'Immutable stock ledger'; COMMENT ON TABLE dbo.notifications IS 'In-app user notifications'; COMMENT ON TABLE dbo.auditlogs IS 'Administrative and workflow audit trail'; COMMENT ON TABLE dbo.systemsettings IS 'Operational configuration'; COMMENT ON TABLE dbo.idempotencykeys IS 'Workflow replay protection'; COMMENT ON TABLE dbo.automationoutbox IS 'Transactional integration events';
CREATE INDEX IF NOT EXISTS ix_users_roleid ON dbo.users(roleid); CREATE INDEX IF NOT EXISTS ix_products_category_active ON dbo.products(categoryid,isactive,isfeatured); CREATE INDEX IF NOT EXISTS ix_variants_product ON dbo.productvariants(productid); CREATE INDEX IF NOT EXISTS ix_reservations_customer_status ON dbo.reservations(customerid,reservationstatusid,expiresat); CREATE INDEX IF NOT EXISTS ix_queue_status_joined ON dbo.queueentries(queuestatusid,joinedat); CREATE INDEX IF NOT EXISTS ix_transactions_customer_created ON dbo.transactions(customerid,createdat); CREATE INDEX IF NOT EXISTS ix_movements_variant_created ON dbo.inventorymovements(productvariantid,createdat); CREATE INDEX IF NOT EXISTS ix_notifications_user_read ON dbo.notifications(recipientuserid,isread,createdat); CREATE INDEX IF NOT EXISTS ix_audit_entity_created ON dbo.auditlogs(entity,createdat); CREATE INDEX IF NOT EXISTS ix_outbox_claim ON dbo.automationoutbox(status,nextattemptat,createdat);

INSERT INTO dbo.roles(rolename) VALUES('Customer'),('Staff'),('Admin') ON CONFLICT DO NOTHING;
INSERT INTO dbo.reservationstatuses(statusname) VALUES('Pending'),('Confirmed'),('Preparing'),('Ready for Pickup'),('Completed'),('Cancelled'),('Expired') ON CONFLICT DO NOTHING;
INSERT INTO dbo.queuetypes(queuetypename) VALUES('Express'),('Regular') ON CONFLICT DO NOTHING;
INSERT INTO dbo.queuestatuses(statusname) VALUES('Waiting'),('Serving'),('Skipped'),('Completed'),('Left') ON CONFLICT DO NOTHING;
INSERT INTO dbo.inventorymovementtypes(movementtypename) VALUES('Reserve'),('Release'),('Sale'),('Adjust'),('Restock') ON CONFLICT DO NOTHING;
INSERT INTO dbo.transactionstatuses(statusname) VALUES('Completed'),('Cancelled') ON CONFLICT DO NOTHING;
INSERT INTO dbo.paymentmethods(paymentmethodname) VALUES('Cash'),('Other') ON CONFLICT DO NOTHING;
INSERT INTO dbo.systemsettings(settingkey,settingvalue,datatype,description) VALUES('ReservationExpiryDays','7','Integer','Days before a reservation expires'),('LowStockDefault','5','Integer','Default low-stock threshold'),('ReferenceCounter','126','Integer','Next business reference counter') ON CONFLICT DO NOTHING;
COMMIT;
